#include <iostream>
using namespace std;

int mdc(int a, int b) {
    while (b != 0) {
        int r = a % b;
        a = b;
        b = r;
    }
    return a;
}

void simplificar(int &num, int &den) {
    int m = mdc(num, den);
    num /= m;
    den /= m;
}

int main() {
    int num, den;
    cout << "Numerador e denominador: ";
    cin >> num >> den;
    int n0 = num, d0 = den;    // guarda a fração original
    simplificar(num, den);
    cout << n0 << "/" << d0 << " = " << num << "/" << den << endl;
    return 0;
}

