#include <iostream>
using namespace std;

void selecaoDecrescente(int v[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int iMaior = i;
        for (int j = i + 1; j < n; j++) {
            if (v[j] > v[iMaior]) iMaior = j;   // > em vez de <
        }
        swap(v[i], v[iMaior]);
    }
}

int main() {
    const int MAX = 50;
    int v[MAX];
    int n;
    cin >> n;
    if (n < 1 || n > MAX) return 0;
    for (int i = 0; i < n; i++) cin >> v[i];
    selecaoDecrescente(v, n);
    for (int i = 0; i < n; i++) cout << v[i] << " ";
    cout << endl;
    return 0;
}

